"""Build the reviewed VARC import from local OCR and visually checked corrections.
The screenshots' green checks / explicit Correct Answer fields are authoritative.
"""
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'samples'
OUT.mkdir(exist_ok=True)
files = {}
for p in (ROOT / 'extraction').glob('*.txt'):
    text = p.read_text(encoding='utf-8')
    number = re.search(r'(\d{2})/24', text)
    if number:
        files[int(number.group(1))] = (p, text)

def join(text):
    return '\n\n'.join(' '.join(p.split()) for p in re.split(r'\n\s*\n', text.strip()))

def passage(n):
    text = files[n][1].split('PASSAGE\n')[1].split('\n\nQUESTION')[0]
    result = join(text.split('\n\n', 1)[1])
    # Punctuation and line-wrap OCR corrections checked against the screenshots.
    for a,b in [('epidemiology”','epidemiology’'), ("arm's- length", "arm's-length"), ('.~ A huge', '... A huge'), ('“mirror-tocracy”\n', '“mirror-tocracy.”\n'), ("true’ We", "true.’ We"), ('{It tells', '(It tells'), ('counter- protesters', 'counter-protesters'), ('role inthe', 'role in the')]:
        result = result.replace(a,b)
    return result

