def question(n):
    prompt, options = (rc | standalone)[n]
    q = {'id':f'va6-q{n:02}', 'sourceNumber':n, 'type':'MCQ' if options else 'TITA', 'prompt':prompt, 'answer':keys[n], 'topic':'Reading comprehension' if n in rc else 'Para summary' if n in (13,14) else 'Odd sentence out' if n in (15,16) else 'Para jumble' if n in (17,18) else 'Sentence placement', 'sourceImages':[files[n][0].stem + '.png']}
    if options:
        q['options'] = [{'id':chr(65+i),'text':text} for i,text in enumerate(options)]
    return q

groups = []
for first, title in [(1,'RC · Psychiatric diagnosis'), (5,'RC · Venture capital'), (9,'RC · Evidence and authority')]:
    groups.append({'id':f'va6-rc{first}', 'title':title, 'stimulus':passage(first), 'questions':[question(n) for n in range(first, first+4)]})
for n in range(13,21):
    groups.append({'id':f'va6-va{n}', 'title':question(n)['topic'], 'questions':[question(n)]})
groups.append({'id':'va6-rc21','title':'RC · Public monuments and racism','stimulus':passage(21),'questions':[question(n) for n in range(21,25)]})
test = {'schemaVersion':1,'id':'ims-varc-section-6-2026','revision':1,'title':'VARC Section Test 6 · 2026','description':'24 questions · 4 RC passages + 8 verbal ability questions. Extracted from your ZIP.','source':{'archive':'VA sectional 6.zip','imageCount':24,'answerKey':'Green correct-option markers and explicit TITA answer fields in supplied review screenshots.','explanations':'Not present in the supplied screenshots.','reviewStatus':'Text and answer keys reviewed against source screenshots.'},'sections':[{'code':'VARC','groups':groups}]}
